// osascript -l JavaScript click_menu.js <pid> <top> <item> [<subitem>]
function run(argv) {
  const se = Application("System Events");
  const proc = se.processes.whose({ unixId: parseInt(argv[0], 10) })[0];
  let menu = proc.menuBars[0].menuBarItems.byName(argv[1]).menus[0];
  let item = menu.menuItems.byName(argv[2]);
  if (argv[3]) item = item.menus[0].menuItems.byName(argv[3]);
  item.click();
  return "clicked";
}
