404	void AppMenus::build_view(wxMenu* menu)
405	{
406	    // The G-code window and the sidebar's layout belong to OrcaSlicer's
407	    // sidebar, which JusPrin does not show. The IDEX toolhead and collision
408	    // volume views are for a few printers, under names few people know.
