415	
416	    // On the Mac the label says what choosing it does; Windows asks for a
417	    // check mark instead of a label that changes.
418	#ifdef __APPLE__
419	    constexpr bool check = false;
420	#else
421	    constexpr bool check = true;
422	#endif
423	    items.push_back(command(menu, _L("Plates and project panel"), {
424	        [this] { m_shell.toggle_left_pane(); },
425	        [this] { return !m_shell.task_open() && m_frame.m_tabpanel->GetSelectedPageName() == TAB_ID_PREPARE; },
426	        check ? [this] { return !m_shell.is_left_pane_collapsed(); } : std::function<bool()>{},
427	        check ? std::function<wxString()>{} : [this] {
428	            return m_shell.is_left_pane_collapsed() ? _L("Show plates and project panel") : _L("Hide plates and project panel");
429	        }}, check));
430	    items.push_back(command(menu, _L("AI panel"), {
431	        [this] { m_shell.toggle_agent_pane(); },
432	        [this] { return project_shown() && m_shell.agent_pane() != nullptr; },
433	        check ? [this] { return !m_shell.is_agent_pane_collapsed(); } : std::function<bool()>{},
434	        check ? std::function<wxString()>{} : [this] {
