584	bool AppMenus::run(int id)
585	{
586	    const auto it = m_commands.find(id);
587	    if (it == m_commands.end() || !it->second.run || (it->second.enabled && !it->second.enabled()))
588	        return false;
589	    // A copy: the command may take these menus apart.
590	    const std::function<void()> command = it->second.run;
591	    command();
592	    return true;
593	}
