601	void AppMenus::on_command(wxCommandEvent& event) { run(event.GetId()); }
602	
603	void AppMenus::on_update_ui(wxUpdateUIEvent& event)
604	{
605	    const auto it = m_commands.find(event.GetId());
606	    if (it == m_commands.end()) {
607	        event.Skip();
608	        return;
609	    }
610	    const Command& command = it->second;
611	    event.Enable(!command.enabled || command.enabled());
612	    if (command.checked)
613	        event.Check(command.checked());
614	    if (command.label)
615	        event.SetText(command.label());
616	}
