624	void AppMenus::on_recent(wxCommandEvent& event)
625	{
626	    const auto it = m_recent_projects.find(event.GetId());
627	    if (it == m_recent_projects.end())
628	        throw std::logic_error("an Open recent row has no project");
629	    // A copy: opening the project refills nothing now, but the list is the
630	    // menu's and the menu is open.
631	    const std::string project = it->second;
632	    m_shell.home_view()->backend().open_project(project);
633	}
