27	// in place, with JusPrin's commands added and a Print and a Printer menu after
28	// View. The same menus show on every screen, Home included; a command that
29	// cannot run there is greyed out, never hidden. An OrcaSlicer item is taken
30	// out only when it can never run in JusPrin. On the Mac they are the menu bar;
31	// on Windows and Linux, OrcaSlicer's File button and its title-bar drop-down.
32	//
33	// OrcaSlicer's items stay in the wxMenu that made them, since their handlers
34	// are bound on it, and an item already where it belongs is not touched: the
35	// Mac hides Quit inside File, and View holds a radio group. Uninstall puts
36	// every menu back as it was.
37	class AppMenus : public wxEvtHandler
38	{
39	public:
40	    AppMenus(MainFrame& frame, ShellController& shell);
41	    ~AppMenus();
42	
43	    AppMenus(const AppMenus&)            = delete;
44	    AppMenus& operator=(const AppMenus&) = delete;
45	
46	    // Throws std::runtime_error when one of OrcaSlicer's items is not where
47	    // its title says, with whatever was already changed left for uninstall()
48	    // to put back. A broken precondition is a std::logic_error.
49	    void install();
50	    void uninstall();
51	
52	    // The menu shortcuts JusPrin answers itself: Cmd/Ctrl+N, O, S, Shift+S
53	    // and R. Whether the command ran or not, true means the key is spent: on
54	    // Home, Cmd+S must not fall through to OrcaSlicer's Save.
55	    bool run_shortcut(const wxKeyEvent& event);
56	
57	    // For the integration harness.
58	    wxMenu* file_menu() const { return m_file; }
59	    wxMenu* view_menu() const { return m_view; }
60	    wxMenu* help_menu() const { return m_help; }
61	    wxMenu* print_menu() const { return m_print; }
62	    wxMenu* printer_menu() const { return m_printer; }
63	    wxMenu* open_recent_menu() const { return m_recent; }
64	
65	private:
66	    struct Command
67	    {
68	        std::function<void()>     run;
69	        std::function<bool()>     enabled; // empty: always
70	        std::function<bool()>     checked; // a check item's state
71	        std::function<wxString()> label;   // a label that follows state
72	    };
73	    // A stock menu as OrcaSlicer built it, to put back.
74	    struct Arranged
75	    {
76	        wxMenu*                  menu;
77	        std::vector<wxMenuItem*> items;
78	    };
79	
80	    wxMenuItem* command(wxMenu* menu, const wxString& label, Command command, bool check = false);
81	    wxMenuItem* separator(wxMenu* menu);
82	    wxMenuItem* submenu(wxMenu* parent, wxMenu* menu, const wxString& label);
83	    void        arrange(wxMenu* menu, const std::vector<wxMenuItem*>& items);
84	    bool        run(int id);
85	
86	    void build_file(wxMenu* menu);
87	    void build_view(wxMenu* menu);
88	    void build_help(wxMenu* menu);
89	    void open_about_from(wxMenu* menu);
90	    wxMenu* build_print();
91	    wxMenu* build_printer();
92	    void    fill_open_recent();
93	
94	    void on_char_hook(wxKeyEvent& event);
95	    void on_command(wxCommandEvent& event);
96	    void on_update_ui(wxUpdateUIEvent& event);
97	    void on_file_menu_open(wxMenuEvent& event);
98	    void on_recent(wxCommandEvent& event);
99	
100	    // What the commands ask.
101	    bool home() const;
102	    bool project_shown() const;
103	
104	    MainFrame&       m_frame;
105	    ShellController& m_shell;
106	    bool             m_installed{false};
107	
108	    std::map<int, Command>               m_commands;
109	    std::vector<std::pair<wxMenu*, int>> m_bound;
110	    std::vector<Arranged>                m_arranged;
111	    // JusPrin's items placed in OrcaSlicer's menus; deleted once those menus
112	    // are put back. Items in JusPrin's own menus go with their menu.
113	    std::vector<wxMenuItem*> m_placed;
114	    // The Mac menu bar's Print and Printer menus.
115	    std::vector<wxMenu*> m_bar_menus;
116	    wxMenuItem*          m_relabeled{nullptr};
117	    wxString             m_relabeled_from;
118	
119	    wxMenu*     m_file{nullptr};
120	    wxMenu*     m_view{nullptr};
121	    wxMenu*     m_help{nullptr};
122	    wxMenu*     m_print{nullptr};
123	    wxMenu*     m_printer{nullptr};
124	    wxMenu*     m_recent{nullptr};
125	    wxMenuItem* m_recent_item{nullptr};
126	    int         m_new_project{0}, m_open{0}, m_save{0}, m_export_project{0}, m_slice{0};
127	    std::map<int, std::string> m_recent_projects; // item id -> project id
