36	// MainFrame's separator before a key OrcaSlicer shows but does not bind as a
37	// macOS key equivalent, which would take the key from typing.
38	#ifdef __APPLE__
39	const wxString kShownKey = " - ";
40	#else
41	const wxString kShownKey = "\t";
42	#endif
43	
44	// One of OrcaSlicer's items, found by the localized label MainFrame gave it,
45	// as the shell finds its Calibration menu.
46	wxMenuItem* stock_item(wxMenu* menu, const wxString& label)
47	{
48	    const wxString text = wxStripMenuCodes(label);
49	    for (wxMenuItem* item : menu->GetMenuItems())
50	        if (!item->IsSeparator() && item->GetItemLabelText() == text)
51	            return item;
52	    throw std::runtime_error("OrcaSlicer's menu item \"" + std::string(text.ToUTF8()) + "\" is not where JusPrin looks for it");
53	}
54	
55	// One of OrcaSlicer's items whose label may end with the key it shows, which
56	// the person can rebind or clear.
57	wxMenuItem* stock_keyed_item(wxMenu* menu, const wxString& label)
58	{
59	    const wxString text = wxStripMenuCodes(label);
60	    for (wxMenuItem* item : menu->GetMenuItems())
61	        if (!item->IsSeparator() && (item->GetItemLabelText() == text || item->GetItemLabelText().StartsWith(text + kShownKey)))
62	            return item;
63	    throw std::runtime_error("OrcaSlicer's menu item \"" + std::string(text.ToUTF8()) + "\" is not where JusPrin looks for it");
64	}
65	
66	wxMenu* stock_submenu(wxMenu* menu, const wxString& label)
67	{
68	    wxMenu* submenu = stock_item(menu, label)->GetSubMenu();
69	    if (submenu == nullptr)
70	        throw std::runtime_error("OrcaSlicer's \"" + std::string(label.ToUTF8()) + "\" item has no submenu");
71	    return submenu;
72	}
73	
74	std::vector<wxMenuItem*> items_of(wxMenu* menu)
75	{
76	    std::vector<wxMenuItem*> items;
77	    for (wxMenuItem* item : menu->GetMenuItems())
78	        items.push_back(item);
79	    return items;
80	}
81	
82	// A menu's items less `removed`, without a separator left at either end or
83	// next to another one.
84	std::vector<wxMenuItem*> without(wxMenu* menu, const std::vector<wxMenuItem*>& removed)
85	{
86	    std::vector<wxMenuItem*> kept;
87	    for (wxMenuItem* item : menu->GetMenuItems()) {
88	        if (std::find(removed.begin(), removed.end(), item) != removed.end())
89	            continue;
90	        if (item->IsSeparator() && (kept.empty() || kept.back()->IsSeparator()))
91	            continue;
92	        kept.push_back(item);
93	    }
94	    while (!kept.empty() && kept.back()->IsSeparator())
95	        kept.pop_back();
96	    return kept;
97	}
98	
99	bool holds(wxMenu* menu, const wxMenuItem* item)
100	{
101	    for (const wxMenuItem* held : menu->GetMenuItems())
102	        if (held == item)
103	            return true;
104	    return false;
105	}
106	
107	#ifndef __APPLE__
108	wxMenu* top_submenu(MainFrame& frame, const wxString& label)
109	{
110	    const wxString title = wxStripMenuCodes(label);
111	    for (wxMenuItem* item : frame.topbar()->GetTopMenu()->GetMenuItems())
112	        if (item->IsSubMenu() && item->GetItemLabelText() == title)
113	            return item->GetSubMenu();
