132	void AppMenus::install()
133	{
134	    if (m_installed)
135	        throw std::logic_error("the app menus are already installed");
136	    m_installed = true;
137	#ifdef __APPLE__
138	    wxMenuBar* bar = m_frame.GetMenuBar();
139	    m_file = bar_menu(m_frame, _L("File"));
140	    m_view = bar_menu(m_frame, _L("View"));
141	    m_help = bar_menu(m_frame, _L("Help"));
142	#else
143	    m_file = m_frame.topbar()->GetFileMenu();
144	    if (m_file == nullptr)
145	        throw std::runtime_error("OrcaSlicer's title bar has no File menu");
146	    m_view = top_submenu(m_frame, _L("View"));
147	    m_help = top_submenu(m_frame, _L("Help"));
148	#endif
149	    build_file(m_file);
150	    build_view(m_view);
151	    build_help(m_help);
152	    {
153	#ifdef __APPLE__
154	        wxMenu* edit = bar_menu(m_frame, _L_CONTEXT("Edit", "Menu"));
155	#else
156	        wxMenu* edit = top_submenu(m_frame, _L_CONTEXT("Edit", "Menu"));
157	#endif
158	        // OrcaSlicer leaves Duplicate Current Plate on everywhere. On Home it
159	        // would add a plate to the project behind Home, out of sight. This
160	        // runs before OrcaSlicer's update handler, which the frame bound
161	        // first, and answers for it.
162	        const int id = stock_item(edit, _L("Duplicate Current Plate"))->GetId();
163	        m_frame.Bind(wxEVT_UPDATE_UI, &AppMenus::on_update_ui, this, id);
164	        m_bound.emplace_back(edit, id);
165	        m_commands.emplace(id, Command{{}, [this] { return !home(); }});
166	    }
167	#ifdef __APPLE__
168	    open_about_from(bar->OSXGetAppleMenu());
169	#else
170	    open_about_from(m_help);
171	#endif
172	
173	#ifndef __APPLE__
174	    wxMenu* top = m_frame.topbar()->GetTopMenu();
175	    // Sync Presets pulls presets from OrcaSlicer's cloud, which JusPrin
176	    // accounts are not, and Preset Bundle manages bundles subscribed there.
177	    // Speed Dial is OrcaSlicer's palette of its own commands. Plugins opens
178	    // OrcaSlicer's Python plugin manager; a plugin's page is a tab, and the
179	    // shell hides the tab strip. On the Mac these are File items, which
180	    // build_file leaves out.
181	    const std::vector<wxMenuItem*> top_items =
182	        without(top, {stock_item(top, _L("Sync Presets")), stock_item(top, _L("Preset Bundle")),
183	                      stock_item(top, _L("Open Speed Dial")), stock_item(top, _L("Plugins"))});
184	#endif
185	    // Print and Printer follow View, as an app's own menus do.
186	    wxMenu* print   = build_print();
187	    wxMenu* printer = build_printer();
188	#ifdef __APPLE__
189	    const int view_at = bar->FindMenu(_L("View"));
190	    bar->Insert(view_at + 1, print, _L("Print"));
191	    m_bar_menus.push_back(print);
192	    bar->Insert(view_at + 2, printer, _L("Printer"));
193	    m_bar_menus.push_back(printer);
194	#else
195	    std::vector<wxMenuItem*> items;
196	    for (wxMenuItem* item : top_items) {
197	        items.push_back(item);
198	        if (item->GetSubMenu() == m_view) {
199	            items.push_back(submenu(top, print, _L("Print")));
200	            items.push_back(submenu(top, printer, _L("Printer")));
201	        }
202	    }
203	    arrange(top, items);
204	#endif
205	    m_print   = print;
206	    m_printer = printer;
207	
208	    m_file->Bind(wxEVT_MENU_OPEN, &AppMenus::on_file_menu_open, this);
209	    fill_open_recent();
210	    // MainFrame's own key hook takes these shortcuts for OrcaSlicer's
211	    // commands, and the handler bound last runs first. The shell installs
212	    // during MainFrame's constructor, before that hook is bound, so this
213	    // binds once the constructor is done.
214	    CallAfter([this] {
215	        if (m_installed)
216	            m_frame.Bind(wxEVT_CHAR_HOOK, &AppMenus::on_char_hook, this);
217	    });
218	}
