285	// -- Building ---------------------------------------------------------------
286	
287	wxMenuItem* AppMenus::command(wxMenu* menu, const wxString& label, Command command, bool check)
288	{
289	    auto* item = new wxMenuItem(menu, wxID_ANY, label, wxEmptyString, check ? wxITEM_CHECK : wxITEM_NORMAL);
290	    const int id = item->GetId();
291	    // On the menu, as OrcaSlicer binds its own items off Windows; the frame
292	    // answers the update events, which wx sends to the window.
293	    menu->Bind(wxEVT_MENU, &AppMenus::on_command, this, id);
294	    m_frame.Bind(wxEVT_UPDATE_UI, &AppMenus::on_update_ui, this, id);
295	    m_bound.emplace_back(menu, id);
296	    m_commands.emplace(id, std::move(command));
297	    return item;
298	}
299	
300	wxMenuItem* AppMenus::separator(wxMenu* menu)
301	{
302	    return new wxMenuItem(menu, wxID_SEPARATOR);
303	}
304	
305	wxMenuItem* AppMenus::submenu(wxMenu* parent, wxMenu* menu, const wxString& label)
306	{
307	    return new wxMenuItem(parent, wxID_ANY, label, wxEmptyString, wxITEM_NORMAL, menu);
308	}
309	
310	// Makes `menu` hold `items`, in order. An item of the menu not among them is
311	// taken out and kept; one not yet in it is put in. An item already in its
312	// place is left alone. Every new item of a stock menu is recorded, to be
313	// deleted once uninstall has taken it out again.
314	void AppMenus::arrange(wxMenu* menu, const std::vector<wxMenuItem*>& items)
315	{
316	    if (m_installed) {
317	        m_arranged.push_back({menu, items_of(menu)});
318	        for (wxMenuItem* item : items)
319	            if (!holds(menu, item))
320	                m_placed.push_back(item);
321	    }
322	    for (wxMenuItem* item : items_of(menu))
323	        if (std::find(items.begin(), items.end(), item) == items.end())
324	            menu->Remove(item);
325	    for (size_t at = 0; at < items.size(); ++at) {
326	        if (at < menu->GetMenuItemCount() && menu->FindItemByPosition(at) == items[at])
327	            continue;
328	        if (holds(menu, items[at]))
329	            menu->Remove(items[at]);
330	        menu->Insert(at, items[at]);
331	    }
332	}
333	
334	void AppMenus::build_file(wxMenu* menu)
335	{
336	    wxMenuItem* import_item = stock_item(menu, _L("Import"));
337	    wxMenuItem* export_item = stock_item(menu, _L("Export"));
338	    wxMenu*     exports     = export_item->GetSubMenu();
339	#ifdef __APPLE__
340	    wxMenuItem* quit        = menu->FindChildItem(wxID_EXIT);
341	#else
342	    // A Shortcut::Quit item, whose id is not wxID_EXIT, off macOS.
343	    wxMenuItem* quit        = stock_item(menu, _L("Quit"));
344	#endif
345	    if (exports == nullptr || quit == nullptr)
346	        throw std::runtime_error("OrcaSlicer's File menu has no Export submenu or no Quit item");
347	
348	    // JusPrin keeps every project in its own store and saves as it goes, so
349	    // File opens and saves that store's projects. OrcaSlicer's Open Project,
350	    // Recent files and Save Project read and write the 3MF at its own path;
351	    // a 3MF leaves the store only through Export.
352	    wxMenuItem* new_project = command(menu, _L("New project") + "\tCtrl+N", {[this] {
353	        m_shell.home_view()->backend().new_project();
354	    }});
355	    m_new_project = new_project->GetId();
356	    wxMenuItem* open = command(menu, _L("Open…") + "\tCtrl+O", {[this] {
357	        m_shell.home_view()->backend().open_file();
358	    }});
359	    m_open = open->GetId();
360	    m_recent      = new wxMenu();
361	    m_recent_item = submenu(menu, m_recent, _L("Open recent"));
362	    // Enabled from the list fill_open_recent last read.
363	    m_frame.Bind(wxEVT_UPDATE_UI, &AppMenus::on_update_ui, this, m_recent_item->GetId());
364	    m_bound.emplace_back(menu, m_recent_item->GetId());
365	    m_commands.emplace(m_recent_item->GetId(), Command{{}, [this] { return !m_recent_projects.empty(); }});
366	
367	    // Saves now and pins that version, so it is kept, and Version history
368	    // lists it.
